UPDATE characters SET description = 'この物語の主人公。シリーズ開始時点でまだ15歳に過ぎないユリは、自信に満ちており、どんな慈善活動にも積極的に取り組む。彼女は当時のどの女性よりもはるかに豊富な知識を持っており、' WHERE character_id = 'CH013257';
UPDATE characters SET description = 'カメハメ王子は、ゆでたまごの漫画およびアニメシリーズ『キン肉マン』に登場するキャラクターである。4Kids Entertainmentによる『Ultimate Muscle』の翻訳版では、「プリンス・ルー・オー」と改名された。キン肉マンは彼を' WHERE character_id = 'CH006795';
UPDATE characters SET description = 'ミートは、惑星キンニク出身のチュラスコ族の一員であり、惑星全体の利益のために、父のミンチからキンニク族のマユミ・キンニクに託された。その後、ミートは地球へ送り出され、……を回収するために' WHERE character_id = 'CH006781';
UPDATE characters SET description = 'ウルフマンは、かつて「超人相撲」の横綱の座に就いていたが、後に「超人レスリング」に転向した日本の超人相撲選手である。彼は筋肉を徹底的に鍛え上げ、「美しき筋肉」を自慢している。' WHERE character_id = 'CH006820';
UPDATE characters SET description = '身長：201cm（6''6"） 分類：悪魔超人 出身地：バミューダ・トライアングル 超人指数：2,000,000 得意技：ブラックホール吸収、影の移動 タッグチーム：4Dキラーコンボ（ペン' WHERE character_id = 'CH006796';
UPDATE characters SET description = 'バッファローマンは、突進する雄牛をモチーフにした超人で、「強大かつ残忍すぎる」として宇宙の果てへ追放されたと言われる「七つの悪魔超人」の一人である。彼は非常に巨体で、2本の湾曲した' WHERE character_id = 'CH006814';
UPDATE characters SET description = '彼女は、ムギノ・シズリが率いるITEMのメンバーである。  ~!第15巻でシズリがシアーゲ・ハマズラに敗れた後、第19巻で彼女はそのリーダーとなる。!~  強力なサイキッカーであるにもかかわらず、' WHERE character_id = 'CH013585';
UPDATE characters SET description = '身長：133 cm (4''4½") 職業：死神（ヴィゾアード）；第12部隊副隊長（元）  猿垣ひよりは、引船桐生および浦鬼介が隊長を務める第12部隊の元副隊長である。' WHERE character_id = 'CH007036';
UPDATE characters SET description = 'ネリエル・トゥ・オーダーシュヴァンク、通称ネル・トゥは、初登場時には気さくで子供のような性格のアランカルである。彼女のホロウの仮面の残骸が、頭頂部に漫画風の髑髏を形作っている。ネルと' WHERE character_id = 'CH007031';
UPDATE characters SET description = '型破りな風貌のガンジュは、ベスト、スカーフ、バンダナ、そしてゴーグルを身につけている。彼はよく、皆が大きなイノシシに乗っている仲間たちと一緒にいる姿が見られる。ガンジュのイノシシの名前はボニー（愛称で' WHERE character_id = 'CH007029';
UPDATE characters SET description = '彼はアフロヘアの死神で、ほぼオマケの章にのみ登場する。朽木ルキアが死刑判決を受けた後、彼女の代わりに空洞から空倉町を守る任務に就く。空倉町で活動中' WHERE character_id = 'CH007035';
UPDATE characters SET description = '身長：151 cm（4''11"） 階級：第5師団中尉　雛森は明るく気さくな性格で、出会うほとんどの人とすぐに打ち解ける。雛森は基本的に人を信じやすいが、一方で非常に' WHERE character_id = 'CH007025';
UPDATE characters SET description = '人物像： 瀬田宗次郎は、獅子尾誠の右腕であり、獅子尾自身によって鍛え上げられた十代の暗殺者である。宗次郎は「剣気」、つまり感情の欠如で知られている。彼には怒りといった感情がなく、' WHERE character_id = 'CH007480';
UPDATE characters SET description = '斎藤一は、実在の新選組第三隊長をモデルにしています。明治時代、彼は藤田五郎という名で警察官として暮らしていました。『るろうに剣心』シリーズでは、彼は' WHERE character_id = 'CH007491';
UPDATE characters SET description = '身長：158 cm    緋村剣心は、アニメシリーズ『るろうに剣心』の主人公であり、作中では「人斬り抜刀斎」や「抜刀斎・緋村」としても知られている。彼の出自は……' WHERE character_id = 'CH007463';
UPDATE characters SET description = '身長：301 cm (9''10½") 所属：～！麦わら海賊団（現）；サン海賊団（元）；ビッグ・マム海賊団の同盟者（元）；七武海（元）； 竜宮王国（辞任）；インペルダウン（元）]!~ P' WHERE character_id = 'CH007803';
UPDATE characters SET description = '「食文化研究クラブ」の創設メンバー3人のうちの1人である1年生。クラブの中で最も背が低く、学生課への設立申請書および修正申請書の作成を担当した。' WHERE character_id = 'CH009380';
UPDATE characters SET description = '六つ子の長男でありリーダーであると同時に、グループの中で最も戦闘能力が高い。1993年の単発エピソード『おそ松くん、大人になる』では、典型的なサラリーマンとなり、未婚のままである。彼の名前は' WHERE character_id = 'CH010563';
UPDATE characters SET description = 'イヤミは、フランス出身だと自称する、とても派手でいたずら好きな男だ。彼の最も特徴的な点は、3本の大きな出っ歯、細い口ひげ、そしてビートルズ風の髪型である。彼は自分自身を' WHERE character_id = 'CH010570';
UPDATE characters SET description = '六つ子のライバル。身長はすごく低いけれど、彼らと同じ年齢だ。彼の最も特徴的なのは、大きくて丸い目と、ハゲた頭の上にある一本の髪の毛だ。彼の好きな食べ物は' WHERE character_id = 'CH010568';
UPDATE characters SET description = '生年：996年　トルフィンは、亡き父から受け継いだ一対の双剣を携えた勇敢な若者である。彼は、妥当な報酬を提示してくれる相手なら誰からでも仕事を引き受ける冷酷な傭兵団のリーダー、アスケラッドと共に旅をしている。 さらに、アスケラッドはトルフィンの父・トースを殺した張本人であり、トルフィンがアスケラッドと共に旅をしている唯一の理由は、決闘で彼を打ち負かし、父の誇りを取り戻すためである。トルフィンが望んでいるのは、ただ父の誇りを取り戻すことだけだ。' WHERE character_id = 'CH014069';
UPDATE characters SET description = 'エイナーはイングランド北部出身の男性で、奴隷として売られてしまった。彼はデンマークにたどり着き、そこでトルフィンと出会う。エイナーはトルフィンと共に、主人から二人に貸与された土地を耕作することで、奴隷の身から抜け出そうと奮闘している。' WHERE character_id = 'CH014070';
UPDATE characters SET description = 'スヴェルケルはケティルの年老いた父親で、デンマークのユトランド半島にある息子の農場の敷地内で暮らしている。' WHERE character_id = 'CH014071';
UPDATE characters SET description = 'ケティルの農場で農作業の手伝いをしている元奴隷。' WHERE character_id = 'CH014072';
UPDATE characters SET description = 'クヌートの首席家臣であり、彼の武術の師範でもあった。' WHERE character_id = 'CH014074';
UPDATE characters SET description = '「バグ・アイズ」というあだ名で知られるトーフィンは、レイフ・エリクソンと共に活動する商人である。元奴隷だったバグ・アイズは、レイフが彼をトールの息子トーフィンだと誤って思い込み、買い取ったのである。' WHERE character_id = 'CH014075';
UPDATE characters SET description = '生年：965年' WHERE character_id = 'CH014077';
UPDATE characters SET description = '彼はラグナーの兄弟だ。' WHERE character_id = 'CH014078';
UPDATE characters SET description = 'ケティルの妻。' WHERE character_id = 'CH014079';
UPDATE characters SET description = 'スヴェイン王の娘であり、ハーラルドとクヌートの妹。' WHERE character_id = 'CH014080';
UPDATE characters SET description = 'クヌートの専属護衛を務める兵士。' WHERE character_id = 'CH014083';
UPDATE characters SET description = 'ケティルの奴隷の一人で、彼の専属の侍女兼側室を務めている。アルンハイドは親切で勤勉、誠実な性格であり、トラブルを起こさずに奴隷としての生活を乗り切ろうと最善を尽くしている。' WHERE character_id = 'CH014084';
UPDATE characters SET description = 'トルケルはヨムスヴァイキングの将軍であり、ヨムスヴァイキングの首長の弟である。戦いを愛する巨漢のトルケルは、同胞のヴァイキングと戦うことこそがより大きな挑戦になると考え、デンマーク軍から離反してイングランドの傭兵となった。 この戦いを愛する心こそが、彼をカンヌート王子のデンマーク王位継承への支持へと駆り立てる。トールクェルが離反する前は、彼と共に戦い、深く尊敬しており、本編ではその息子トルフィンにも親しみを抱いている。彼はトルフィンと二度、決闘を繰り広げる。' WHERE character_id = 'CH014085';
UPDATE characters SET description = 'アスケラッドは、小規模ながらも強力なヴァイキングの一団の指揮官であり、その成功はアスケラッドの並外れた知略によるものであった。『ヴィンランド・サガ』の本編より10年前、アスケラッドはトルフィンの父であるトースを暗殺するという依頼を引き受けた。 イングランドへのヴァイキングの侵攻と戦争の最中、彼はトルフィンが自分に対して抱く復讐心を巧みに利用し、才能ある若き戦士を自分の配下に留めておいた。アスケラッドは本作において最も腕の立つ戦士の一人であり、特に' WHERE character_id = 'CH014086';
UPDATE characters SET description = 'スヴェイン王の長男であり、クヌートおよびエストリッドの兄弟。' WHERE character_id = 'CH014087';
UPDATE characters SET description = 'クヌート王の使者。' WHERE character_id = 'CH014088';
UPDATE characters SET description = '彼女はトルフィンの姉である。トルフィンが父トルスの仇を討つために旅立った後、彼女は家事をこなし、母の世話をしている。' WHERE character_id = 'CH014090';
UPDATE characters SET description = '生年：996年　クヌートはデンマークの王子である。当初、彼は臆病で女々しい性格として描かれており、美少年のような外見を持ち、家臣のラグナルがいなければまともに振る舞えない。こうした特徴に加え、彼の強いキリスト教信仰も相まって、共に働くヴァイキングたちから嘲笑の的となっている。' WHERE character_id = 'CH014091';
UPDATE characters SET description = 'アイナーの妹。' WHERE character_id = 'CH014092';
UPDATE characters SET description = 'イングランドとウェールズのほぼ全土を征服しつつ、北方の領土の支配権も維持し続けたデンマーク王。クヌートの父。' WHERE character_id = 'CH014093';
UPDATE characters SET description = 'ビョルンはアスケラッドの副官であり、戦闘そのものを愛して戦う屈強な男だ。彼はバーサーカーであり、特定のキノコを摂取することで、凄まじい狂乱状態に入ることができる。' WHERE character_id = 'CH014095';
UPDATE characters SET description = 'トースは、その驚異的な戦闘能力から「ヨムのトロール」という異名を持つヨムスヴァイキングの将軍、トルフィンの父である。トースは子供たちが生まれた後、戦いに疲れを感じ、自らの死を偽装して戦線を離れ、平和を愛する農夫として暮らすようになった。  トースは、アスケラッドやトルケルといった強敵を一騎打ちで打ち負かしたことから、本作に登場する最強の戦士と広く見なされている。その強さは際立っており、フロキでさえ、部隊を率いていても彼と直接対決することを躊躇したほどであった。' WHERE character_id = 'CH014096';
UPDATE characters SET description = '彼はクヌート王子の首席顧問である。ラグナルは、頭の両脇に生えている非常に長く、黒く、縮れた髪を除けば、頭は禿げている。深くくぼんだ目のすぐ上に、非常に太く黒い眉毛がある。また、特に頬や、濃いひげのすぐ上の部分には、非常に深いしわがある。  （出典：ヴィンランド・サーガ Wiki）' WHERE character_id = 'CH014097';
UPDATE characters SET description = 'レイフの旅の仲間。' WHERE character_id = 'CH014098';
UPDATE characters SET description = 'かつてはヴァイキングの戦士だったが、後に奴隷となった。' WHERE character_id = 'CH014099';
UPDATE characters SET description = 'ケティルに雇われたスネークの傭兵団の一員。' WHERE character_id = 'CH014100';
UPDATE characters SET description = 'スネークの「ゲスト」の一員。' WHERE character_id = 'CH014103';
UPDATE characters SET description = 'アリは、アイスランドのトルフィンが住む村の出身です。' WHERE character_id = 'CH014104';
UPDATE characters SET description = '彼女はトルフィンとイルヴァの母であり、トースの妻である。' WHERE character_id = 'CH014105';
UPDATE characters SET description = '親族：<a href="https://anilist.co/character/89509/Akemi-Aizawa">アケミ</a> （母）、<a href="https://anilist.co/character/89510/Gorou-Aizawa">ゴロウ</a>（父）  トモは、おてんばな性格で格闘技に抜群の才能を持ち、幼なじみの<a href="https://anilist.co/character/89182/Junichirou-Kubota">ジュンイチロウ</a>の心を射止めたいと切に願っている女子高生だ。 運動能力の高さにもかかわらず、彼女は自分の男っぽいところについてコンプレックスを抱いており、b' WHERE character_id = 'CH014106';
UPDATE characters SET description = '親族：<a href="https://anilist.co/character/187792/Misaki-Gundou">ミサキ</a>（母）  軍堂ミズズは『トモちゃんは女の子！』の第三の主人公である。 彼女は <a href="https://anilist.co/character/89181/相沢トモ">トモ</a>と<a href="https://anilist.co/character/89182/Junichirou-Kubota">ジュン</a>の幼なじみであり、同級生です。 彼女は狡猾で、時にはサディスティックな一面もあり、よくジュンをからかう。しかし、彼女は友人を大切にする一面もあり、トモとジュンの関係が進展することを嫌っている。' WHERE character_id = 'CH014107';
UPDATE characters SET description = '親族：<a href="https://anilist.co/character/187795/Ferris-Olston">フェリス</a> （母）、<a href="https://anilist.co/character/89511/Kousuke-Misaki">コウスケ</a> （遠縁のいとこ）　キャロルは、<a href="https://anilist.co/character/89181/Tomo-Aizawa">トモ</a>、 <a href="https://anilist.co/character/89182/Junichirou-Kubota">ジュン</a>、そして<a href="https://anilist.co/character/89183/Misuzu-Gundou">ミズズ</a>の同級生であり友人です。 英国出身の、人形のような顔立ちの美しい学生で、物事をありのままに表現するタイプです。' WHERE character_id = 'CH014108';
UPDATE characters SET description = '久保田淳一郎は、『トモちゃんは女の子！』の第二の主人公である。 彼は<a href="https://anilist.co/character/89181/Tomo-Aizawa">トモ</a>の隣人であり、幼なじみ、道場の仲間、そして高校の同級生である。ハンサムだが、トモが自分に好意を抱いていることに気づいていない。 彼はトモの父親が経営する道場で定期的に稽古をしており、トモが他の男子に気を配っていると嫉妬してしまう。  <div rel="spoiler">彼は<a href="https://anilist.co/character/89183/Misuzu-Gundou">ミズズ</a>とは仲が悪く、' WHERE character_id = 'CH014109';
UPDATE characters SET description = '三船は当初、親友の小川と同様にあまりいい人とは言えなかった。彼女は相沢トモに喧嘩を仕掛けようとしたが、それは賢明な判断ではなかった。しかし、それは誤解だったため、それ以来、二人はある程度仲良くなった。' WHERE character_id = 'CH014110';
UPDATE characters SET description = 'トモのお母さん。' WHERE character_id = 'CH014111';
UPDATE characters SET description = '彼女はキャロルの母親であり、エディ・オルストンの妻である。フェリスは娘と同じように、おっちょこちょいで軽薄な性格だ。自宅の正門から家に戻ろうとして、道に迷ってしまったことさえある。彼女はイギリスで母親が経営するカフェでウェイトレスとして働き、わずか13歳の時にエディと出会った。' WHERE character_id = 'CH014112';
UPDATE characters SET description = '彼女はミズズの母親です。' WHERE character_id = 'CH014113';
UPDATE characters SET description = '2年生で、空手部のキャプテン。キャロルのいとこであり、幼なじみでもある。彼もイギリス系の血を引いている。トモを心から尊敬している。' WHERE character_id = 'CH014114';
UPDATE characters SET description = '田辺竜美は、ジュンの同級生であり友人だ。彼は、ミズズに「トモに近づかないで」と言われた際、彼女から睨みつけられて以来、彼女に恋心を抱くようになった。' WHERE character_id = 'CH014116';
UPDATE characters SET description = 'トモの父親。相沢道場を経営しており、トモとジュンの両方を指導してきた。' WHERE character_id = 'CH014117';
UPDATE characters SET description = '小川はトモの同級生であり、三船の親友だ。' WHERE character_id = 'CH014118';
UPDATE characters SET description = 'ハンサムで、頭が良くて、優しい男の子。彼は学年で一番人気があり、よく「プリンス」と呼ばれている。成績も優秀で、多くの女子から注目を集めている。' WHERE character_id = 'CH014119';
UPDATE characters SET description = '椎名真昼の母親。' WHERE character_id = 'CH014120';
UPDATE characters SET description = '第1部隊の隊長であり、東京マンジギャングの創設者の一人。バジは荒々しい性格の持ち主だ。アドレナリンが湧き上がるスリルをこよなく愛しており、マイキー自身も「彼は特に理由もなく、ただ気分で通りすがりの人を殴り飛ばすような男だ」と語っている。戦闘中も、彼のトレードマークであるニヤリとした笑みを絶やさない。' WHERE character_id = 'CH014121';
UPDATE characters SET description = '柴泰寿の妹であり、柴八海の上の姉である。' WHERE character_id = 'CH014123';
UPDATE characters SET description = 'ヒナタとナオトの母親。' WHERE character_id = 'CH014124';
UPDATE characters SET description = '彼は東京マンジギャングの創設メンバーの一人であり、同ギャングの元第3分隊長である。' WHERE character_id = 'CH014125';
UPDATE characters SET description = '彼女は三ツ矢隆の妹であり、三ツ矢マナの姉である。' WHERE character_id = 'CH014126';
UPDATE characters SET description = '立花ヒナタと立花ナオトの父親。' WHERE character_id = 'CH014127';
UPDATE characters SET description = '長年にわたる孤独のせいで、イザナは冷酷で残忍な人物となってしまった。精神的に不安定になっただけでなく、絶対的な権力を手に入れようと躍起になっている。イザナは、第8代ブラックドラゴンズの元リーダーであり、天竺の元会長でもある。彼は「天竺編」の主要な敵役の一人である。' WHERE character_id = 'CH014128';
UPDATE characters SET description = 'キサキは『東京リベンジャーズ』の主要な敵役である。特に、トーマンの頂点へと猛スピードで駆け上がったことで知られている。   木崎は冷酷で狡猾、野心家であり、目標を達成するためなら手段を選ばない。体格は平均的だが、恐怖によって支配するその力は、自分より強い者さえも従わせる。物語全体を通じた彼の行動は、すべて東京で最も強力かつ影響力のある犯罪者になることを目指して展開される。' WHERE character_id = 'CH014129';
UPDATE characters SET description = '東京マンジギャングの創設者の一人であり、かつてヴァルハラのナンバー3を務めた。カズトラは心に深い傷を抱えている。幼い頃、家庭内暴力の渦中で、母親と父親のどちらかを選ばざるを得なかったのだ。家族というものが根本的に存在しなかったため、彼は他の幸せな家族を軽蔑するようになった。 子供たちが親と仲睦まじく過ごす姿を見るといった、ごく些細な出来事さえも、カズトラの心の傷を刺激し、彼を深く苛立たせた。' WHERE character_id = 'CH014130';
UPDATE characters SET description = 'イヌピの姉。' WHERE character_id = 'CH014131';
UPDATE characters SET description = '「ブラックドラゴン」の第10代リーダーであり、ハッカイとユズハの兄。  タイジュは残忍で暴力的だ。敵を苦しめることを楽しみ、他人の安否にはほとんど関心を示さない。実の兄弟姉妹でさえ例外ではない。相手が誰であろうと、性別を問わず構わない。カトリック教徒であり、背中には十字架のタトゥーを入れている。' WHERE character_id = 'CH014132';
UPDATE characters SET description = 'エルドメイド・ディティジョンの部下' WHERE character_id = 'CH014133';
UPDATE characters SET description = '種族：精霊　職業：教師　「教育の大樹」に関する噂や伝承から生まれた精霊であり、学校そのものを体現する存在である。エニユニエンは、その高さがどこまでも続き、雲を突き抜け、まるで天を貫きそうなほどにそびえ立つ大樹である。 エニユニエンの内部には、彼が生徒たちに教えるために使える教室がある。' WHERE character_id = 'CH014134';
UPDATE characters SET description = 'アノスによって生み出された「七大古妖帝」の一人。' WHERE character_id = 'CH014135';
UPDATE characters SET description = '2000年前の悪魔。アノスの配下の中では、シン・レグリアに次ぐ、2番目に腕の立つ剣士とされている。' WHERE character_id = 'CH014136';
UPDATE characters SET description = '「緋色の記念碑」の王、ギリシリス・デロの配下。' WHERE character_id = 'CH014137';
UPDATE characters SET description = '種族：悪魔　四悪王の一人で、「緋色の記念碑王」として知られる。' WHERE character_id = 'CH014138';
UPDATE characters SET description = 'アノスによって生み出された「七大古妖帝」の一人。' WHERE character_id = 'CH014139';
UPDATE characters SET description = 'アノスのクラスの生徒。' WHERE character_id = 'CH014140';
UPDATE characters SET description = 'カノンはアノスと戦う英雄である。彼はアノスと互いに敬意を抱いており、二人は互いを理解し合っているようだ。アノスがカノンに倒される前、アノスは「もし2000年後に再会することがあれば、友達になれたらいいのに」と願っていた。' WHERE character_id = 'CH014141';
UPDATE characters SET description = '魔王学園の生徒であり、「カオス世代」の一人。冥界王エゲス・コードの配下である。' WHERE character_id = 'CH014142';
UPDATE characters SET description = 'アノスによって生み出された「七大魔帝」の一人であり、ネクロン家の当主でもある。' WHERE character_id = 'CH014146';
UPDATE characters SET description = 'アノスによって生み出された「七大魔帝」の一人。' WHERE character_id = 'CH014147';
UPDATE characters SET description = '天の父、秩序を創り出す神、そして神々の父。' WHERE character_id = 'CH014148';
UPDATE characters SET description = 'ガイオス・アンゼムは、アノス・ヴォルディゴードによって生み出された「七人の古の魔帝」の一人である。' WHERE character_id = 'CH014149';
UPDATE characters SET description = '魔王学園の生徒であり、「カオス世代」の一員。' WHERE character_id = 'CH014150';
UPDATE characters SET description = '種族：精霊　職業：情報仲介者　記憶を失った精霊。' WHERE character_id = 'CH014151';
UPDATE characters SET description = 'イドール・アンゼオは、アノス・ヴォルディゴードによって生み出された「七大古の魔帝」の一人である。' WHERE character_id = 'CH014152';
UPDATE characters SET description = 'ミデヘイズの街を支配する魔王であり、クルートとエミリアの父でもある。' WHERE character_id = 'CH014153';
UPDATE characters SET description = 'Instagram　カズキは、同僚であり親友でもあるレイと暮らしており、レイはカズキの身の回りの世話もしている。レイとの主な仕事は、契約の締結、事前の情報収集、そして実行計画の立案である。彼は女性とギャンブルが好きで、コミュニケーション能力にも長けている。料理や掃除も得意で、時折、レイの放漫な生活態度を叱ることもある。   かつては結婚しており、妻は彼の子供を身ごもっていたが、怪しげな仕事が原因で彼女を失ってしまった。' WHERE character_id = 'CH014154';
UPDATE characters SET description = 'レイは口数の少ない男で、カズキがすでに自分の家に居候していることにも特に気にしていない。体力が強く、戦闘能力や射撃の腕前は業界でもトップクラスだ。仕事と私生活をきっちりと区切っており、ほとんどの時間を家でビデオゲームをして過ごしている。 彼の家族は巨大な裏社会の一族であり、両親は彼が幼い頃から、才能ある暗殺者として彼を鍛えてきた。彼は一族間の抗争から逃れることができず、' WHERE character_id = 'CH014155';
UPDATE characters SET description = 'ミリは、無邪気で、元気いっぱいで、何事にもひるまない少女だ。彼女の父親はマフィアのボスであり、人身売買組織の主要な仲介人でもある。母親は、そのボスの愛人だ。 父親を探してホテルに到着した彼女は、銃撃戦に巻き込まれるが、カズキに助けられる。彼女は人懐っこく、カズキを「パパ・カズキ」、レイを「パパ・レイ」と呼んでいる。' WHERE character_id = 'CH014156';
UPDATE characters SET description = '親族：諏訪レイ（息子）' WHERE character_id = 'CH014157';
UPDATE characters SET description = 'レイとカズキに仕事と情報の両方を提供しているカフェのオーナー。' WHERE character_id = 'CH014160';
UPDATE characters SET description = '「あおぞら保育園」の保育士。' WHERE character_id = 'CH014162';
UPDATE characters SET description = '人身売買組織の主要な仲介者。' WHERE character_id = 'CH014165';
UPDATE characters SET description = 'カズキの妊娠中の妻。' WHERE character_id = 'CH014166';
UPDATE characters SET description = 'ユズコの妹であり、カズキの義妹。' WHERE character_id = 'CH014168';
UPDATE characters SET description = 'ミリの母親。マフィアのボスである早見篤と不倫関係を持った後、シングルマザーとして出産した。' WHERE character_id = 'CH014170';
UPDATE characters SET description = 'タイプ：機械生命体　謎めいた、唯一無二の存在。機械生命体であるにもかかわらず、その外見はアンドロイドに酷似している。' WHERE character_id = 'CH014172';
