UPDATE characters SET description = 'ルーシーは、奏すずの同級生であり友人です。物静かで内気なタイプですが、何でもかんでもSNSに投稿したくなるような写真を撮るのが大好きです。普段はいつも鳥羽弥生と一緒にいます。' WHERE character_id = 'CH014719';
